"""Stickelberger sign certificate: splitting type of x^3 + a x + b mod p via gcd(f, x^p - x),
checked against Euler's criterion for the discriminant."""
from __future__ import annotations

Poly = list[int]  # coefficients, lowest degree first, reduced mod p


def trim(f: Poly) -> Poly:
    while f and f[-1] == 0:
        f.pop()
    return f


def poly_mod(f: Poly, g: Poly, p: int) -> Poly:
    f = trim([c % p for c in f])
    g = trim([c % p for c in g])
    inv = pow(g[-1], p - 2, p)
    while len(f) >= len(g):
        q = f[-1] * inv % p
        shift = len(f) - len(g)
        for i, c in enumerate(g):
            f[shift + i] = (f[shift + i] - q * c) % p
        trim(f)
    return f


def poly_mulmod(f: Poly, g: Poly, m: Poly, p: int) -> Poly:
    prod = [0] * (len(f) + len(g) - 1) if f and g else []
    for i, a in enumerate(f):
        for j, b in enumerate(g):
            prod[i + j] = (prod[i + j] + a * b) % p
    return poly_mod(prod, m, p)


def poly_powmod_x(e: int, m: Poly, p: int) -> Poly:
    """x^e mod (m, p) by square-and-multiply."""
    result: Poly = [1]
    base: Poly = poly_mod([0, 1], m, p)
    while e:
        if e & 1:
            result = poly_mulmod(result, base, m, p)
        base = poly_mulmod(base, base, m, p)
        e >>= 1
    return result


def poly_gcd(f: Poly, g: Poly, p: int) -> Poly:
    f, g = trim([c % p for c in f]), trim([c % p for c in g])
    while g:
        f, g = g, poly_mod(f, g, p)
    return f


def sign_certificate(a: int, b: int, p: int) -> dict[str, object]:
    f: Poly = [b % p, a % p, 0, 1]
    xp = poly_powmod_x(p, f, p)                      # x^p mod f
    xp_minus_x = xp + [0] * max(0, 2 - len(xp))
    xp_minus_x[1] = (xp_minus_x[1] - 1) % p
    g = poly_gcd(f, xp_minus_x, p)
    n_roots = len(g) - 1 if g else 3                 # g = 0 would mean f | x^p - x
    delta = -4 * a ** 3 - 27 * b ** 2
    euler = pow(delta % p, (p - 1) // 2, p)
    legendre = 0 if delta % p == 0 else (1 if euler == 1 else -1)
    sign = -1 if n_roots == 1 else 1
    return {"p": p, "roots": n_roots, "type": {3: "1+1+1", 1: "1+2", 0: "3"}[n_roots],
            "sign": sign, "legendre(disc)": legendre, "consistent": legendre == sign}


if __name__ == "__main__":
    for p in (5, 7, 11, 13, 43, 47, 1_000_003):
        print("x^3-2  ", sign_certificate(0, -2, p))
        print("x^3+x+1", sign_certificate(1, 1, p))

"""Mutual information of a type channel under the uniform measure on a finite set."""
from __future__ import annotations

import math
from collections import Counter, defaultdict
from itertools import permutations
from typing import Callable, Hashable, Sequence, TypeVar

A = TypeVar("A")


def entropy(values: Sequence[Hashable]) -> float:
    n = len(values)
    if n == 0:
        return 0.0
    return -sum(c / n * math.log2(c / n) for c in Counter(values).values())


def type_channel_information(s: Sequence[A], g: Callable[[A], Hashable],
                             T: Callable[[A], Hashable]) -> dict[str, float]:
    """Return H(g), H(g|T) and I(g;T) for the uniform measure on s."""
    n = len(s)
    fibres: dict[Hashable, list[Hashable]] = defaultdict(list)
    for x in s:
        fibres[T(x)].append(g(x))
    h = entropy([g(x) for x in s])
    hc = sum(len(f) / n * entropy(f) for f in fibres.values())
    i = h - hc
    return {"H(g)": h, "H(g|T)": hc, "I(g;T)": 0.0 if abs(i) < 1e-12 else i}


def sign(perm: tuple[int, ...]) -> int:
    inversions = sum(1 for i in range(len(perm)) for j in range(i + 1, len(perm)) if perm[i] > perm[j])
    return -1 if inversions % 2 else 1


def cycle_type(perm: tuple[int, ...]) -> tuple[int, ...]:
    seen, out = set(), []
    for i in range(len(perm)):
        if i not in seen:
            j, length = i, 0
            while j not in seen:
                seen.add(j)
                j = perm[j]
                length += 1
            out.append(length)
    return tuple(sorted(out, reverse=True))


if __name__ == "__main__":
    for n in range(2, 7):
        G = list(permutations(range(n)))
        print(f"S_{n}:", type_channel_information(G, sign, cycle_type))

"""Conductor detection: the smallest modulus m for which the sign bit of Frobenius is a
function of p mod m on a sample of primes."""
from __future__ import annotations

from typing import Callable, Optional


def primes_up_to(n: int) -> list[int]:
    sieve = bytearray([1]) * (n + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytearray(len(sieve[i * i :: i]))
    return [i for i in range(n + 1) if sieve[i]]


def sign_bit(a: int, b: int) -> Callable[[int], bool]:
    """Frobenius is odd  <=>  x^3 + a x + b has exactly one root mod p."""
    return lambda p: sum(1 for x in range(p) if (x ** 3 + a * x + b) % p == 0) == 1


def detect_conductor(bit: Callable[[int], bool], primes: list[int], max_m: int = 2000) -> Optional[int]:
    values = {p: bit(p) for p in primes}
    for m in range(1, max_m + 1):
        seen: dict[int, bool] = {}
        if all(seen.setdefault(p % m, v) == v for p, v in values.items()):
            return m
    return None


if __name__ == "__main__":
    for a, b in ((0, -2), (1, 1), (-1, 1), (2, 3)):
        d = -4 * a ** 3 - 27 * b ** 2
        ps = [p for p in primes_up_to(4000) if p != 2 and d % p]
        print(f"x^3 + {a}x + {b}: disc = {d}, detected conductor = {detect_conductor(sign_bit(a, b), ps)}")

"""Frobenius orbit of a root: in F_p[x]/(f) for an irreducible depressed cubic f, compute
r, r^p, r^(p^2), verify they are the three roots in a 3-cycle, and extract the Vandermonde
delta = (r1-r2)(r1-r3)(r2-r3), which lies in F_p and squares to the discriminant."""
from __future__ import annotations

Elt = tuple[int, int, int]  # c0 + c1*t + c2*t^2 in F_p[t]/(t^3 + a t + b)


def mul(u: Elt, v: Elt, a: int, b: int, p: int) -> Elt:
    c = [0] * 5
    for i in range(3):
        for j in range(3):
            c[i + j] += u[i] * v[j]
    for k in (4, 3):                       # t^k = t^(k-3) * (-a t - b)
        top, c[k] = c[k], 0
        c[k - 2] -= a * top
        c[k - 3] -= b * top
    return (c[0] % p, c[1] % p, c[2] % p)


def power(u: Elt, e: int, a: int, b: int, p: int) -> Elt:
    r: Elt = (1, 0, 0)
    while e:
        if e & 1:
            r = mul(r, u, a, b, p)
        u = mul(u, u, a, b, p)
        e >>= 1
    return r


def sub(u: Elt, v: Elt, p: int) -> Elt:
    return tuple((x - y) % p for x, y in zip(u, v))  # type: ignore[return-value]


def frobenius_orbit(a: int, b: int, p: int) -> dict[str, object]:
    assert all((x ** 3 + a * x + b) % p for x in range(p)), "f must have no root mod p"
    r1: Elt = (0, 1, 0)                    # the class of t: a root of f
    r2 = power(r1, p, a, b, p)
    r3 = power(r2, p, a, b, p)
    back = power(r3, p, a, b, p)
    delta = mul(mul(sub(r1, r2, p), sub(r1, r3, p), a, b, p), sub(r2, r3, p), a, b, p)
    disc = (-4 * a ** 3 - 27 * b ** 2) % p
    return {"r1": r1, "r2 = r1^p": r2, "r3 = r2^p": r3, "r3^p == r1": back == r1,
            "sum of roots == 0": tuple((x + y + z) % p for x, y, z in zip(r1, r2, r3)) == (0, 0, 0),
            "delta": delta, "delta in F_p": delta[1] == delta[2] == 0,
            "delta^2 == disc": (delta[0] ** 2 - disc) % p == 0}


if __name__ == "__main__":
    print("x^3+x+1 mod 5 :", frobenius_orbit(1, 1, 5))
    print("x^3-2   mod 7 :", frobenius_orbit(0, -2, 7))
    print("x^3-2   mod 13:", frobenius_orbit(0, -2, 13))
    print("x^3+x+1 mod 19:", frobenius_orbit(1, 1, 19))

