"""Conductor spectrum: I(sign of Frobenius ; p mod m) as a function of the modulus m."""
from __future__ import annotations

import math
from collections import Counter

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt


def primes_up_to(n: int) -> list[int]:
    sieve = bytearray([1]) * (n + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytearray(len(sieve[i * i :: i]))
    return [i for i in range(n + 1) if sieve[i]]


def one_root(a: int, b: int, p: int) -> bool:
    return sum(1 for x in range(p) if (x ** 3 + a * x + b) % p == 0) == 1


def entropy(values: list) -> float:
    n = len(values)
    return -sum(c / n * math.log2(c / n) for c in Counter(values).values())


def mutual_info(bits: list[bool], labels: list[int]) -> float:
    n = len(bits)
    fibres: dict[int, list[bool]] = {}
    for b, l in zip(bits, labels):
        fibres.setdefault(l, []).append(b)
    return entropy(bits) - sum(len(f) / n * entropy(f) for f in fibres.values())


def main(bound: int = 4000, max_m: int = 100) -> None:
    ps = [p for p in primes_up_to(bound) if p not in (2, 3, 31)]
    cubics = {"$x^3-2$  ($\\Delta=-108$)": (0, -2), "$x^3+x+1$  ($\\Delta=-31$)": (1, 1)}
    ms = list(range(1, max_m + 1))
    fig, axes = plt.subplots(2, 1, figsize=(11, 6.5), sharex=True)
    for ax, (label, (a, b)), colour, cond in zip(axes, cubics.items(), ("#2e86ab", "#e4572e"), (3, 31)):
        bits = [one_root(a, b, p) for p in ps]
        info = [mutual_info(bits, [p % m for p in ps]) for m in ms]
        ax.bar(ms, info, color=[colour if m % cond == 0 else "#bbbbbb" for m in ms], width=0.8)
        ax.axhline(entropy(bits), ls="--", lw=1, color="k")
        ax.set_ylabel("bits")
        ax.set_ylim(0, 1.08)
        ax.set_title(f"{label}: I(sign ; p mod m); full bit exactly at multiples of {cond}")
    axes[-1].set_xlabel("modulus m")
    fig.suptitle("Same one-bit channel, different conductor", fontsize=14)
    fig.tight_layout()
    fig.savefig("conductor_spectrum.png", dpi=150)
    print("saved conductor_spectrum.png")


if __name__ == "__main__":
    main()

"""Chebotarev in action: running frequencies of the three splitting types for two S3 cubics."""
from __future__ import annotations

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt


def primes_up_to(n: int) -> list[int]:
    sieve = bytearray([1]) * (n + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytearray(len(sieve[i * i :: i]))
    return [i for i in range(n + 1) if sieve[i]]


def n_roots(a: int, b: int, p: int) -> int:
    return sum(1 for x in range(p) if (x ** 3 + a * x + b) % p == 0)


def main(bound: int = 15000) -> None:
    cubics = {"$x^3-2$": (0, -2, -108), "$x^3+x+1$": (1, 1, -31)}
    fig, axes = plt.subplots(1, 2, figsize=(12, 4.5), sharey=True)
    for ax, (label, (a, b, d)) in zip(axes, cubics.items()):
        ps = [p for p in primes_up_to(bound) if p > 3 and d % p]
        counts = {3: 0, 1: 0, 0: 0}
        xs: list[int] = []
        series: dict[int, list[float]] = {3: [], 1: [], 0: []}
        for i, p in enumerate(ps, start=1):
            counts[n_roots(a, b, p)] += 1
            xs.append(p)
            for k in series:
                series[k].append(counts[k] / i)
        for k, name, col, target in ((3, "1+1+1 (identity)", "#6a994e", 1 / 6),
                                     (1, "1+2 (transposition, odd)", "#e4572e", 1 / 2),
                                     (0, "3 (3-cycle)", "#2e86ab", 1 / 3)):
            ax.plot(xs, series[k], color=col, label=name, lw=1.3)
            ax.axhline(target, color=col, ls="--", lw=0.8)
        ax.set_xscale("log")
        ax.set_title(f"{label}: splitting-type frequencies")
        ax.set_xlabel("p")
    axes[0].set_ylabel("running frequency")
    axes[1].legend(loc="upper right", fontsize=9)
    fig.suptitle("Both fields converge to the S3 proportions 1/6 : 1/2 : 1/3", fontsize=13)
    fig.tight_layout()
    fig.savefig("chebotarev_frequencies.png", dpi=150)
    print("saved chebotarev_frequencies.png")


if __name__ == "__main__":
    main()
